// =============================================================
// Build Email Report — samkoBuilds branded
// Paste into the "Build Email Report" Code node
// Mode: "Run Once for All Items"
// Works with V1 and V2 (issue_type column only shows if it exists)
// =============================================================

// ---- Brand tokens (samkoBuilds Brand Guidelines v1.0) ----
const C = {
  core:    '#0D0D0F', // Charcoal Core – page background
  c900:    '#17171B', // card surface
  c800:    '#232328', // table header / alt rows
  c500:    '#55555F', // borders
  c300:    '#8C8C96', // muted text
  paper:   '#F2EFE9', // main text
  orange:  '#FF6B35', // Signal Orange – accent only
  error:   '#E5484D', // URGENT badge
  warning: '#F2B705', // Normal badge
};
const SANS = "Montserrat, 'Segoe UI', Arial, sans-serif";
const MONO = "'JetBrains Mono', Consolas, 'Courier New', monospace";

// ---- Get the rows (works after an Aggregate node OR directly after Filter) ----
const rows = $json.data ?? $input.all().map(i => i.json);

// ---- Helpers ----
// Escape text so customer comments can't break the HTML
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').trim();

const fmtTime = (iso) => {
  try { return DateTime.fromISO(iso).setZone('Europe/Sofia').toFormat('dd.MM.yyyy HH:mm'); }
  catch (e) { return esc(iso); }
};

const badge = (text, color) =>
  `<span style="display:inline-block;padding:3px 8px;border:1px solid ${color};border-radius:4px;color:${color};font-family:${MONO};font-size:11px;letter-spacing:1px;">${esc(text).toUpperCase()}</span>`;

const hasIssue = rows.some(r => r.issue_type);

// ---- Sort: urgent first, then strongest emotion ----
rows.sort((a, b) =>
  (Number(b.is_urgent) - Number(a.is_urgent)) ||
  ((b.sentiment_strength ?? 0) - (a.sentiment_strength ?? 0)));

const total  = rows.length;
const urgent = rows.filter(r => r.is_urgent).length;
const runAt  = DateTime.now().setZone('Europe/Sofia').toFormat('dd.MM.yyyy HH:mm');

// ---- Stat tile ----
const stat = (label, value, color) => `
  <td width="50%" style="padding:16px;background:${C.c900};border:1px solid ${C.c500};border-radius:6px;">
    <div style="font-family:${MONO};font-size:11px;letter-spacing:1.5px;color:${C.c300};">${label}</div>
    <div style="font-family:${SANS};font-size:28px;font-weight:700;color:${color};padding-top:4px;">${value}</div>
  </td>`;

// ---- Table rows ----
const th = (t) => `<th align="left" style="padding:10px 12px;font-family:${MONO};font-size:11px;letter-spacing:1px;font-weight:400;color:${C.c300};border-bottom:1px solid ${C.c500};">${t}</th>`;
const td = (content, extra = '') => `<td valign="top" style="padding:12px;border-bottom:1px solid ${C.c800};${extra}">${content}</td>`;

const bodyRows = rows.map((r, i) => {
  const urgentRow = !!r.is_urgent;
  const bg = i % 2 ? C.c900 : C.core;
  const leftBar = urgentRow ? `border-left:3px solid ${C.error};` : `border-left:3px solid transparent;`;
  return `<tr style="background:${bg};">
    ${td(badge(r.priority ?? (urgentRow ? 'Urgent' : 'Normal'), urgentRow ? C.error : C.warning), leftBar)}
    ${td(`<div style="font-family:${SANS};font-size:14px;font-weight:500;color:${C.paper};">${esc(r.customer_name)}</div>
          <div style="font-family:${MONO};font-size:11px;color:${C.c300};padding-top:2px;">#${esc(r.feedback_id)} · ${fmtTime(r.analyzed_at)}</div>`)}
    ${td(`<div style="font-family:${SANS};font-size:14px;font-weight:300;line-height:1.6;color:${C.paper};">“${esc(r.Feedback)}”</div>
          ${r.urgency_reason ? `<div style="font-family:${MONO};font-size:11px;color:${C.c300};padding-top:6px;">→ ${esc(r.urgency_reason)}</div>` : ''}`)}
    ${hasIssue ? td(`<span style="font-family:${MONO};font-size:12px;color:${r.issue_type === 'Critical issue' ? C.orange : C.c300};">${esc(r.issue_type)}</span>`) : ''}
    ${td(`<span style="font-family:${MONO};font-size:12px;color:${C.paper};">${esc(r.sentiment_strength)}</span>`, 'text-align:center;')}
    ${td(`<span style="font-family:${MONO};font-size:12px;color:${C.paper};">${esc(r.sentiment_confidence)}</span>`, 'text-align:center;')}
  </tr>`;
}).join('');

// ---- Full email ----
const html = `
<div style="margin:0;padding:24px 0;background:${C.core};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:760px;margin:0 auto;background:${C.core};font-family:${SANS};color:${C.paper};">

  <!-- Header: monogram + wordmark -->
  <tr><td style="padding:24px 28px 20px 28px;border-bottom:1px solid ${C.c800};">
    <table role="presentation" cellpadding="0" cellspacing="0"><tr>
      <td style="width:40px;height:40px;background:${C.c900};border-radius:6px;text-align:center;vertical-align:middle;font-family:${SANS};font-size:20px;font-weight:700;">
        <span style="color:${C.paper};">s</span><span style="color:${C.orange};">B</span>
      </td>
      <td style="padding-left:12px;font-family:${SANS};font-size:18px;font-weight:600;color:${C.paper};">samkoBuilds</td>
    </tr></table>
  </td></tr>

  <!-- Title -->
  <tr><td style="padding:28px 28px 8px 28px;">
    <div style="font-family:${MONO};font-size:11px;letter-spacing:2px;color:${C.orange};">FEEDBACK ANALYZER · RUN ${runAt}</div>
    <div style="font-family:${SANS};font-size:26px;font-weight:700;line-height:1.15;color:${C.paper};padding-top:8px;">Customer feedback that needs attention</div>
    <div style="font-family:${SANS};font-size:15px;font-weight:300;line-height:1.6;color:${C.c300};padding-top:8px;">
      Every comment was scored for sentiment${hasIssue ? ' and checked for blocking issues (refunds, wrong or missing orders, payment problems)' : ''}. Urgent items are listed first.
    </div>
  </td></tr>

  <!-- Stats -->
  <tr><td style="padding:16px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="8" style="border-collapse:separate;"><tr>
      ${stat('NEEDS ATTENTION', total, C.paper)}
      ${stat('URGENT', urgent, urgent ? C.error : C.paper)}
    </tr></table>
  </td></tr>

  <!-- Table -->
  <tr><td style="padding:8px 28px 24px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ${C.c800};border-collapse:collapse;">
      <tr style="background:${C.c800};">
        ${th('PRIORITY')}${th('CUSTOMER')}${th('FEEDBACK')}${hasIssue ? th('ISSUE') : ''}${th('STRENGTH')}${th('CONF.')}
      </tr>
      ${bodyRows || `<tr><td colspan="6" style="padding:20px;font-family:${SANS};font-weight:300;color:${C.c300};">No negative feedback in this run.</td></tr>`}
    </table>
  </td></tr>

  <!-- Footer -->
  <tr><td style="padding:20px 28px;border-top:1px solid ${C.c800};font-family:${MONO};font-size:11px;color:${C.c300};line-height:1.6;">
    Generated automatically by an n8n workflow · Sentiment by LLM (Large Language Model), so scores are estimates — check before acting.<br>
    <a href="https://samkobuilds.com" style="color:${C.orange};text-decoration:none;">samkobuilds.com</a> · Building the skills to build with AI.
  </td></tr>

</table>
</div>`;

return [{
  json: {
    subject: urgent
      ? `[samkoBuilds] ${urgent} urgent / ${total} feedback items need attention`
      : `[samkoBuilds] ${total} feedback items need attention`,
    html,
    total_items: total,
    urgent_count: urgent,
  },
}];

